-- 5002 🏋️ Exercises from the book "technical-practices-to-maximise-performance-50-practices-youth-to-pro-training-w" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'technical-practices-to-maximise-performance-50-practices-youth-to-pro-training-w');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Speed and agility technical circuit', 'technical', 'unopposed', NULL, 52, 52, 'Practice 1', 'Juventus', 'Quick footwork and explosive movement patterns combined with passing in a circuit.', '40 x 30 m split into two mirrored circuits, each with hurdle sets, poles, speed rings and a mannequin, plus a central passing station.', 'Players step through 3 low hurdles, sprint round a pole, jump forward through 5 hurdles, sprint round another pole, then do quick feet through rings. They then join a 4-player passing combination, following their pass; the last receiver dribbles past the mannequin, passes to the next starter and switches to the other circuit.', 'Follow your pass; finish the circuit then cross to the other group.', NULL, NULL, '18-20', 18, 20, '40 x 30 m', 40.0, 30.0, 15.0, false, false, false, NULL, 10),
  ('In and out dribble and pass circuit', 'technical', 'unopposed', NULL, 53, 53, 'Practice 2', 'Real Madrid', 'Fast passing, first touch and beating an opponent with a dribbling move.', '25 x 25 m square with 4 mannequins in the middle and a cone gate on each side with 3 players queued behind it.', 'A player from each gate dribbles into the middle, does a skill (chop, step-over etc.) to go past the mannequin on its left, then passes to the next player in the next gate, rotating A-B-C-D. After 3 full laps the coach names a new skill.', NULL, 'Make it a race: groups compete to finish a full circuit fastest.', 'Close control and balance round the mannequin; accurate, weighted pass; good first touch.', '12-16', 12, 16, '25 x 25 m', 25.0, 25.0, 15.0, false, false, false, NULL, 20),
  ('Body shape receiving rotation in threes', 'passing_unopposed', 'unopposed', 'in_possession', 54, 54, 'Practice 3', NULL, 'Explosive movement between passes, constant rotation and an open body shape to play forward.', '20 x 5 m channel; 2-3 players at the ends and 1 in the middle (groups of 3-4).', 'End player A passes to middle player B, who takes it on the half-turn and plays to the far end player C. A and B swap places, and C then passes to the new middle player as it continues.', NULL, NULL, 'Meet the ball on the half-turn and take it on the back foot; pass quality; sharp movement after passing. Rest every 30-60 seconds with some dynamic mobility.', 'groups of 3-4', 3, 4, '20 x 5 m', 20.0, 5.0, 10.0, false, false, false, NULL, 30),
  ('Open up and play around mannequins', 'passing_unopposed', 'unopposed', 'in_possession', 55, 55, 'Practice 4', 'Bayern Munich', 'Back-foot receiving, pass placement and body shape when receiving.', '20 x 20 m area with cones and mannequins in a five-point passing pattern (A-E); 7-8 players.', 'A plays diagonally to B, who opens up round a mannequin and passes across to C; C opens up round a mannequin and plays forward to D, who opens round a cone and passes to E; E does the same and plays back to position A for the next player. Everyone follows their pass.', 'Follow your pass; rotation A-B-C-D-E-A.', NULL, 'Pass quality and weight, receive on the half-turn, quick combination play, good movement to receive, intensity of rotation.', '7-8', 7, 8, '20 x 20 m', 20.0, 20.0, 15.0, false, false, false, NULL, 40),
  ('Receiving and support passing combinations', 'passing_unopposed', 'unopposed', 'in_possession', 56, 56, 'Practice 5', NULL, 'Passing combinations, movement, support play and body shape.', '15 x 15 m area with mannequins marking six positions A-F; 10-12 players.', 'A plays to B and gets a one-two back; A then finds C, who opens up round a mannequin and drives a firm ground pass to D. D plays to E, E to F, and F back to position A for the next player.', 'Follow your pass; rotation A-B-C-D-E-F-A.', NULL, 'Quality and weight of pass at high speed, quick combinations, open up to receive on the back foot, intensity of rotation.', '10-12', 10, 12, '15 x 15 m', 15.0, 15.0, 15.0, false, false, false, NULL, 50),
  ('Up-back-through and switch combination', 'passing_unopposed', 'unopposed', 'in_possession', 57, 57, 'Practice 6', NULL, 'Up, back and through combination passing plus switching the play.', '20 x 20 m area with a central square and mannequins near the corners; 14-16 players, two balls starting at once from opposite ends (A and E).', 'A/E play diagonally into B/F, who set for C/G to switch the play to D/H. D/H receive behind the mannequin, take a directional first touch away from their feet and dribble to the far start position. As soon as they round the mannequin the next two players start new balls.', 'Follow your pass; rotation A-B-C-D-E-F-G-H-A.', NULL, 'Receive with the back foot when opening up behind the mannequin.', '14-16', 14, 16, '20 x 20 m', 20.0, 20.0, 15.0, false, false, false, NULL, 60),
  ('End to end third man runs', 'passing_unopposed', 'unopposed', 'in_possession', 58, 58, 'Practice 7', NULL, 'Combination passing, timing of runs and playing forward via the third man.', '30 x 15 m; pairs queued at both ends and two fixed central players (M1, M2); 12-14 players.', 'A1 passes into M1, who sets for A2 to play forward to M2; M2 lays it into the path of A1''s run so A1 can pass to end player B1. A1 and A2 go to the far end and the next pair (B1, B2) comes back the other way with the same middle men.', NULL, 'Coach changes the combination sequence after a while.', 'Play forward and time the runs.', '12-14', 12, 14, '30 x 15 m', 30.0, 15.0, 15.0, false, false, false, NULL, 70),
  ('Triangle open up rotational passing', 'passing_unopposed', 'unopposed', 'in_possession', 59, 59, 'Practice 8', 'Ajax', 'Movement, back-foot receiving, first touch and quick accurate passing.', 'Triangle of cones about 12 m a side; groups of 7 spread over the three corners.', 'Each receiver checks away from the cone, then opens up and takes the first touch out of the feet round the cone before passing sharply to the next corner. Players follow in rotation A-B-C-D.', 'Follow your pass.', 'Practice 9 adds a one-two at each corner.', 'Create space, receive on the back foot, good first touch, quick and well-weighted pass.', 'groups of 7', 7, 7, '12 x 12 x 12 m triangle', 12.0, 12.0, 15.0, false, false, false, NULL, 80),
  ('Triangle rotation with one-two support', 'passing_unopposed', 'unopposed', 'in_possession', 60, 60, 'Practice 9', 'Ajax', 'Movement, body shape, back-foot receiving and quick accurate passing with support play.', 'Same 12 m cone triangle as Practice 8, groups of 7.', 'A passes to B and moves towards him to support; a one-two is played at each corner as the ball travels round. The receiver moves around the cone to take the return pass, then plays on to the next corner.', 'Follow your pass; rotation A-B-C-D-A.', 'Second of four Ajax triangle variations.', 'Set the return pass with correct weight in front of the cone; curved, well-timed run; receive on the back foot.', 'groups of 7', 7, 7, '12 x 12 x 12 m triangle', 12.0, 12.0, 15.0, false, false, false, NULL, 90),
  ('Ajax triangle one-two and set-back', 'passing_unopposed', 'unopposed', 'in_possession', 61, 61, 'Practice 10', 'Ajax', 'Movement, body shape, receiving on the back foot and quick accurate passing.', 'Triangle of three cones about 12 m a side; queue at A, players at B and C stations.', 'A passes to B and follows in support; B lays off, A plays forward to C who sets back for B; B then passes across for C''s curved run round the cone, C passes on to the next player at D.', 'B and C check away from their cone before showing to receive; rotate A>B>C>D>A.', 'Third of four Ajax triangle variations.', 'Set the ball in front of the cone with the right weight for the next player.', 'groups of 7', 7, 7, '12 x 12 x 12 m', 12.0, 12.0, 15.0, false, false, false, NULL, 100),
  ('Ajax triangle free decision combinations', 'passing_unopposed', 'unopposed', 'in_possession', 62, 62, 'Practice 11', 'Ajax', 'Movement, body shape, back foot receiving and quick accurate passing with free choice of combination.', 'Same 12 m triangle as the previous Ajax drills, players spread over the stations with a queue at the start.', 'Players choose their own combinations and directions round the triangle (one-twos, set-backs, curved runs) instead of a fixed sequence.', 'Rotation stays A>B>C>D>A whatever the combination.', 'Final progression of the Ajax triangle series.', 'Correct weight on set passes in front of the cone; create space and time curved runs.', 'groups of 7', 7, 7, '12 x 12 x 12 m', 12.0, 12.0, 15.0, false, false, false, NULL, 110),
  ('Aerial passing triangle around mannequins', 'passing_unopposed', 'unopposed', 'in_possession', 63, 63, 'Practice 12', NULL, 'High-speed aerial passing and receiving with an open back-foot body shape.', '15 m triangle with a mannequin at each corner; small group spread over three stations.', 'A lofts a pass over the mannequin to B, who checks off it, receives on the back foot and lofts on to C; C continues to the next player at A. Each passer sprints to the next station to put pressure on the receiver.', 'Rotation A>B>C>A, continuous.', NULL, 'Strike the ball with different parts of the foot; accurate passes; directional first touch that sets up the next pass.', 'groups of 4', 4, 4, '15 x 15 x 15 m', 15.0, 15.0, 10.0, false, false, false, NULL, 120),
  ('High-speed triangle one-two combination', 'passing_unopposed', 'unopposed', 'in_possession', 64, 64, 'Practice 13', NULL, 'Speed, angle and weight of pass, timing of movement and ball control.', '15 m triangle of cones, queue at A and players at B and C.', 'Simple start: A to B to C, C dribbles back to A. Progression: A to B, B lays back for A''s movement (one-two), A plays forward to C who sets back for B running on; B passes across for C, who dribbles a few steps and passes to the next player.', 'Rotation A>B>C>A.', 'Progress from the simple three-pass sequence to the one-two and set-back version.', 'Angle and weight of pass plus timing of movement.', '9-12', 9, 12, '15 x 15 x 15 m', 15.0, 15.0, 15.0, false, false, false, NULL, 130),
  ('Up, back and through give-and-go Y', 'passing_unopposed', 'unopposed', 'in_possession', 65, 65, 'Practice 14', NULL, 'Speed, direction and angle of pass, timing of movement and ball control.', 'Two mirrored Y shapes side by side in a 20 x 15 m area, a ball at each start.', 'A plays a one-two with B (who checks off his cone), then passes diagonally forward to C; C sets for the onrushing B, who plays C in to run on and dribble back to the start. Repeat with the next player.', 'Two balls at once, one per side; rotation A>B>C>A.', NULL, 'For the B-C combination: timing, positioning, scanning and awareness.', '10-12', 10, 12, '20 x 15 m', 20.0, 15.0, 15.0, false, false, false, NULL, 140),
  ('Up, back, through and around Y with angled pass', 'passing_unopposed', 'unopposed', 'in_possession', 66, 66, 'Practice 15', NULL, 'Pass quality, rotations, receiving on the half-turn and angled forward passing.', '20 x 20 m area: start A at the bottom, two mannequins in the middle with B and C, wide players D1/D2 at the top and E1/E2 on the sides.', 'A passes to B, who checks off the cone and sets back for C; C plays diagonally forward to D2, who checks off and passes diagonally back to E2; E2 plays to the start for the next player. Then the same runs down the left side.', 'Rotation A>B>C>D>E>A.', 'Alternate the sequence to the left side (shown as an alternative pattern).', 'Ball speed, timing of the move off the cone, body shape, receive on the back foot.', '8-10', 8, 10, '20 x 20 m', 20.0, 20.0, 15.0, false, false, false, NULL, 150),
  ('Y passing race with dribble back', 'passing_unopposed', 'unopposed', 'in_possession', 67, 67, 'Practice 16', NULL, 'Receiving on the back foot, body shape, accurate passing and dribbling.', 'Y shape in a 25 x 10 m area; several groups of 7, each on its own Y.', 'Example: A plays a one-two with B then passes to C; B moves forward for C''s next pass and plays across for D, who runs onto it and dribbles back to the start. The next player goes.', 'Groups compete: most consecutive rotations in the set time wins; a mistake resets the count to zero. Coach can change the combination each set.', NULL, 'Good timing of movement to create space; quick, accurately weighted passing.', 'groups of 7', 7, 7, '25 x 10 m', 25.0, 10.0, 15.0, false, false, false, NULL, 160),
  ('Diamond double-movement scanning circuit', 'passing_unopposed', 'unopposed', 'in_possession', 68, 68, 'Practice 17', NULL, 'First and second movements, timing, body shape and scanning.', 'Diamond of cones about 20 x 15 m with two balls starting at A and C.', 'Fixed order A>B>C>D, but B and D''s first movement (long or short) tells A and C whether to pass short or long; the receiver either moves long to receive short and turns, or moves short to receive long and plays first time.', 'Rotation A>B>C>D>A.', 'Add overlaps and set-backs to the sequence, still stressing scanning and awareness.', 'Scan before receiving and read the receiver''s movement; open body shape.', '8-10', 8, 10, '20 x 15 m', 20.0, 15.0, 15.0, false, false, false, NULL, 170),
  ('Cross-shape diamond pass and opposite run', 'passing_unopposed', 'unopposed', 'in_possession', 69, 69, 'Practice 18', NULL, 'Reactions, body shape to receive and quick accurate passing.', 'Small 12 x 12 m diamond of cones, players at each corner.', 'Ball goes round the diamond A>B>C>D>A; after passing, each player sprints across to the opposite cone (A to C, B to D) while avoiding team-mates crossing the middle.', 'Each player checks away from the cone before showing to receive.', NULL, 'Double movements to make space; body shape to receive; quality of pass.', 'groups of 8', 8, 8, '12 x 12 m', 12.0, 12.0, 15.0, false, false, false, NULL, 180),
  ('Diamond play wide and through combinations', 'passing_unopposed', 'unopposed', 'in_possession', 70, 70, 'Practice 19', NULL, 'Combination passing, receiving on the back foot and body shape.', 'Diamond of cones in a 20 x 15 m area, players queued at A, B, C and D.', 'A passes to B and supports; B checks away, drops and plays a one-two with A; A drives a firm ground pass to C, who opens up behind the cone. The same pattern repeats with C and D, finishing with C passing to the next player at A.', 'Rotation A>B>C>D>A.', NULL, 'Weight and quality of pass, receive on the half-turn, quick combinations, high intensity of rotations.', '8-10', 8, 10, '20 x 15 m', 20.0, 15.0, 15.0, false, false, false, NULL, 190),
  ('One-touch diamond support combinations', 'passing_unopposed', 'unopposed', 'in_possession', 71, 71, 'Practice 20', NULL, 'High ball speed, one-touch play and body shape to receive.', '12 x 12 m diamond of cones, players at A, B, C and D.', 'Simple start: A>B>C>D following passes, D returns to A. Progression: A plays a one-two with C, passes wide to B, B plays a one-two with C, then switches across to D, who passes to the start.', 'Rotation A>B>C>D>A; one-touch at sprint intensity.', 'Simple pass-and-follow version, then the one-two progression.', 'Pass quality, ball speed, rotation, intensity and body shape when receiving.', '6-8', 6, 8, '12 x 12 m', 12.0, 12.0, 15.0, false, false, false, NULL, 200),
  ('Inter Milan diamond quick combinations', 'passing_unopposed', 'unopposed', 'in_possession', 72, 72, 'Practice 21', 'Inter Milan', 'Angle of pass, receiving on the back foot, body shape and quick combinations.', '30 x 25 m diamond of cones with a cone in the middle; stations A to F; two balls start at A and D.', 'A passes to B, who opens up, carries forward and plays wide to C; C opens up and passes to D. Simultaneously D plays a one-two with E and passes wide to F, who drops off; F sets for E, who threads F round the cone (give and go), and F passes to A.', 'Everyone follows their pass; rotation A>B>C>D>E>F>A.', NULL, 'Open up on the back foot; first touch guides the next pass.', 'groups of 10-12', 10, 12, '30 x 25 m', 30.0, 25.0, 15.0, false, false, false, NULL, 210),
  ('Barcelona small-space figure of 8', 'passing_unopposed', 'unopposed', 'in_possession', 73, 73, 'Practice 22', 'FC Barcelona', 'Technical passing and receiving, quick combinations and through passing.', '25 x 25 m area with two linked diamonds (figure of 8): stations A to H.', 'A>B>C; C plays a one-two with D and passes diagonally to E; E plays a one-two with F, passes forward to G, G a one-two with H, then diagonally to the start. Everyone rotates.', 'Rotation A through H and back to A.', 'Add a second ball starting at E; C and G must avoid ball collisions on the crossing passes.', 'High ball speed, quality passing and correct body shape to progress.', 'groups of 12', 12, 12, '25 x 25 m', 25.0, 25.0, 15.0, false, false, false, NULL, 220),
  ('Barcelona one-touch box to target players', 'passing_unopposed', 'unopposed', 'in_possession', 74, 74, 'Practice 23', 'FC Barcelona', 'Combinations, one-touch passing and body shape to play forward.', 'Central 15 x 15 m box with four players inside and a target player in a zone 5 m off each end (25 x 15 m total).', 'A target player passes in; all four inside players must touch the ball, one touch each, before it goes to the target on the far side. Then back the other way, end to end.', 'One-touch inside the box; all four must touch it.', '1: more passes inside the box. 2: players touch a cone after each pass to raise intensity and create space.', 'Open body shape to see team-mates and the next pass.', 'groups of 6', 6, 6, '25 x 15 m', 25.0, 15.0, 15.0, false, false, true, NULL, 230),
  ('Individual receiving, turning and dribbling channels', 'technical', 'unopposed', 'in_possession', 75, 75, 'Practice 24', NULL, 'First touch, reactions, body shape to receive and quick accurate passing.', '25 x 10 m channels, each with a small central square and a mini goal at each side; feeder A at one end, worker B in the square.', 'A passes either side of the square; B moves out, takes a good first touch and finishes into the near mini goal, then back into the square. Variation: A passes into the square, B receives, dribbles to a cone, turns, dribbles back and returns the ball. Players swap roles.', 'B starts each rep from the central square.', 'Three stations shown (1/3 to 3/3) building from passing into goals to receive-turn-dribble.', 'Receive on the back foot and pass with quality.', 'groups of 4', 4, 4, '25 x 10 m', 25.0, 10.0, 15.0, true, false, true, NULL, 240),
  ('Ladder passing and back-foot shooting', 'finishing', 'unopposed', 'in_possession', 76, 76, 'Practice 25', NULL, 'High-speed passing, body shape, back-foot receiving and shooting.', 'Half pitch: two mirrored ladders of mannequins up each side towards a goal with GK; groups start at A and E.', 'Players check off their mannequin, receive on the back foot, turn sharply and pass to the next station, following the pass; D and H turn and shoot then join the other group. E starts after A so the two finishers do not shoot together.', 'Rotation A/E > B/F > C/G > D/H > opposite group.', 'Change the order to A/E>C/G>B/F>D/H>C/G>shoot, with C/G and D/H setting back for the next runner.', 'Quality movement to receive, body shape, back-foot receiving, quick decisions.', 'groups of 12-14', 12, 14, 'half pitch', NULL, NULL, 15.0, true, true, true, NULL, 250),
  ('Man City one-touch passing race to goals', 'finishing', 'unopposed', 'in_possession', 77, 77, 'Practice 26', 'Manchester City', 'Body shape, one-touch passing and dynamic accurate finishing.', 'Area as shown on the edge of the box: three team zones (A, B, C) each with mannequins and a target mini goal; teams of 8.', 'Race 1: pass in rotation round the mannequins, D receives and shoots at a target goal. Race 2: order A>C>B>D with a switch and D opening up behind a mannequin to shoot. Race 3: one-two, pass, one-two and C plays D through to shoot. Coach can call Change to rotate teams clockwise.', 'Teams race at once; most rotations in the set time wins each race.', 'Coach can change the direction of rotation.', NULL, 'groups of 8', 8, 8, 'as shown', NULL, NULL, 15.0, true, false, true, NULL, 260),
  ('Receiving under pressure Y with dribble', 'passing_opposed', 'passive', 'in_possession', 84, 84, 'Extensive Practice 1', NULL, 'Forward passing, receiving on the half-turn, pressing and dribbling.', '35 x 20 m Y shape: queue at A, B at a central cone, C1 and C2 at the two top cones.', 'A passes to B, who checks off the cone, receives on the half-turn and passes to C2, then sprints to press C2 passively; C2 dribbles back to the start. Next player repeats with B playing to C1 on the left.', 'Rotation A>B>C>A.', 'C plays a one-two with B and then lofts a pass to the next player at A.', 'Receive at an angle on the half-turn with the back foot for quicker control and more options.', '10-12', 10, 12, '35 x 20 m', 35.0, 20.0, 15.0, false, false, false, NULL, 270),
  ('Changing lines and angles combination circuit', 'passing_unopposed', 'unopposed', 'in_possession', 85, 85, 'Extensive Practice 2', NULL, 'Forward passing, combination play and receiving on the back foot.', '35 x 30 m area with mannequins; stations A to H on different lines and angles round the area.', 'A>B>C, C comes off a mannequin, turns and passes to D; D does the same to E, who moves inside off the cone and plays F; F passes forward to H, who sets for G (double movement), and G passes to the next player at A.', 'Players must receive on a different line or angle each time; rotation A to H and back.', NULL, 'Weight of pass, half-turn execution, smooth rotations, high intensity.', '10-12', 10, 12, '35 x 30 m', 35.0, 30.0, 15.0, false, false, false, NULL, 280),
  ('PSG switching play receiving rotations', 'passing_unopposed', 'unopposed', 'in_possession', 86, 86, 'Extensive Practice 3', 'PSG', 'Passing patterns focused on switching play.', '40 x 30 m split in two halves, each with 4 mannequins and 5-6 players at A, B, C, D.', 'A passes to B, who opens up and switches diagonally to C; C opens round a mannequin and plays to D, who does the same; D finishes with a diagonal switch to the next player at A.', 'Rotation A>B>C>D>A, same pattern in each half.', NULL, 'Back-foot directional first touch; control and accuracy throughout.', '10-12', 10, 12, '40 x 30 m', 40.0, 30.0, 15.0, false, false, false, NULL, 290),
  ('Two-team rotational passing race to the box', 'passing_unopposed', 'unopposed', 'in_possession', 87, 87, 'Extensive Practice 4', NULL, 'Forward passing, tactical combinations and progressive passing patterns.', 'Half pitch with cone stations for two teams of 7 working the same pattern side by side, finishing near the box.', 'Each team passes A>B>C>D>E; when E receives he dribbles through a cone gate before the next player starts with a new ball from A.', 'Race: first team to complete 5 rotations without mistakes wins.', 'Change the combination or movements, or allow left foot only.', 'Move at an angle to meet the pass with an open body shape.', '14-16', 14, 16, 'half pitch', NULL, NULL, 15.0, false, false, false, NULL, 300),
  ('Barcelona figure of 8 support play', 'passing_unopposed', 'unopposed', 'in_possession', 88, 88, 'Extensive Practice 5', 'FC Barcelona', 'Technical passing and receiving, quick combinations and support play.', '40 x 30 m hexagon-style figure of 8 with stations A to H, two inside players in the middle.', 'A>B>C; C plays inside diagonally to D, who drops, opens up and plays on to E. The mirror image runs on the other side E>F>G>H>A.', 'Rotation A through H and back.', 'Add a second ball from E; D and H avoid collisions on crossing passes.', 'High ball speed, quality passing, body shape to play out.', '16-18', 16, 18, '40 x 30 m', 40.0, 30.0, 15.0, false, false, false, NULL, 310),
  ('Barcelona figure of 8 with third-man support runs', 'passing_unopposed', 'unopposed', 'in_possession', 89, 89, 'Extensive Practice 6', 'FC Barcelona', 'Technical passing and receiving, quick combinations and support runs.', 'Same 40 x 30 m figure of 8 with stations A to H.', 'A to B, who sets back for C after a double movement; C passes inside to D, who drops and passes for the third-man support run of B, who plays across to E. Mirrored on the other side E>F>G>H>F>A.', 'Everyone follows their pass to the next position.', 'Progression of Practice 5.', 'Control, accuracy, timing of movement and body shape.', '14-16', 14, 16, '40 x 30 m', 40.0, 30.0, 15.0, false, false, false, NULL, 320),
  ('Ajax diamond gates one-twos', 'passing_unopposed', 'unopposed', 'in_possession', 90, 90, 'Extensive Practice 7', 'Ajax', 'Movement, timing, body shape to receive and positional passing.', '40 x 30 m with cone gates in a diamond and a small central square; two balls start at A and D.', 'A/D play a one-two with B/E, who set back for A/D to pass to C/F; C/F play a give and go with A/D, then pass to the next player at A/D.', 'Rotation A>B>C>D>E>F>A.', 'When C/F set back, A/D play a long pass to the next waiting player instead.', 'Open the body to see more and pass quicker.', '16-20', 16, 20, '40 x 30 m', 40.0, 30.0, 15.0, false, false, false, NULL, 330),
  ('Rotational combinations with overlapping third-man runs', 'passing_unopposed', 'unopposed', 'in_possession', 91, 91, 'Extensive Practice 8', NULL, 'Technical passing, quick combinations and third-man runs.', '30 x 30 m with mannequins; stations A to H, two balls from A and E.', 'A/E play a one-two with B/F then pass wide to C/G; C/G pass inside to B/F, who run round the mannequin to support, then thread a pass for the overlapping third-man run of D/H, who finish with a pass to A/E.', 'Rotation A through H and back.', NULL, 'Timing of movement and the weight of B/F''s pass for the overlap.', '18-20', 18, 20, '30 x 30 m', 30.0, 30.0, 15.0, false, false, false, NULL, 340),
  ('Build-up circuit from GK through back line', 'passing_unopposed', 'unopposed', 'in_possession', 92, 92, 'Extensive Practice 9', NULL, 'Build-up skills: passing, receiving, dribbling and movement.', 'Half pitch with stations for GK, LB, LCB, DM, RCB and RB, cones marking each spot.', 'GK passes wide to LB, who dribbles forward, checks and passes to LCB; LCB, DM and RCB receive and pass on (1-2 touch); RB kicks the ball forward, runs onto it and passes back to GK. Then all move up a station.', 'Circuit GK>LB>LCB>DM>RCB>RB>GK; 1-2 touches in the middle.', NULL, 'Effective passing and receiving, control and accuracy at high speed of play.', 'groups of 6', 6, 6, 'half pitch', NULL, NULL, 15.0, false, true, false, NULL, 350),
  ('Build-up circuit with free decisions', 'passing_unopposed', 'unopposed', 'in_possession', 93, 93, 'Extensive Practice 10', NULL, 'Build-up skills with free decision making.', 'Same half-pitch build-up stations GK, LB, LCB, DM, RCB, RB.', 'No set sequence: players choose their own combinations through the back line and midfield, e.g. LB dribbles and passes to DM, RB sprints through a cone gate to receive and passes to GK.', 'Players still move on one station each round GK>LB>LCB>DM>RCB>RB>GK.', 'Variation of Practice 9.', 'Quick decisions under pressure, accurate passing and receiving, communication.', 'groups of 6', 6, 6, 'half pitch', NULL, NULL, 15.0, false, true, false, NULL, 360),
  ('Play out from the back rotational combinations', 'passing_unopposed', 'unopposed', 'in_possession', 94, 94, 'Extensive Practice 11', NULL, 'Forward passing, tactical combinations and running with the ball.', 'Half pitch with cone stations A to H from the penalty box out to the halfway line.', 'Ball goes A>B>C>D>E>F>G>H; H dribbles as fast as possible to deliver to the next player at A, who turns and starts the next rotation.', 'Rotation A through H and back.', '1: change combinations/movements or limit to one foot. 2: two teams race to complete 5-7 rotations first.', 'Pass weight; move before receiving with an open body shape.', '12-14', 12, 14, 'half pitch', NULL, NULL, 15.0, false, false, false, NULL, 370),
  ('Two-team positional build-up copy patterns', 'passing_unopposed', 'unopposed', 'in_possession', 95, 95, 'Extensive Practice 12', NULL, 'Decision making, support angles, body shape and passing range.', 'Pitch area as shown: two teams of 6 (back 4 + 2 holding midfielders, e.g. from a 4-2-3-1) in opposite halves.', 'One team builds up with a freely chosen pattern then passes to the other team, who must copy the same pattern before returning the ball. Swap roles halfway.', 'Free choice of pattern for the starting team; the other copies it.', 'Add a forward who plays for both teams.', 'Support angles and pass weight so team-mates can play quickly.', '12 (2 x 6)', 12, 12, 'as shown', NULL, NULL, 12.0, false, false, false, NULL, 380),
  ('Positional rotational combinations on both sides', 'passing_unopposed', 'unopposed', 'in_possession', 96, 96, 'Extensive Practice 13', NULL, 'Forward passing, tactical combinations and progressive passing patterns.', 'Half pitch, two mirrored groups with mannequins; stations A to F each side, two balls from A1 and A2.', 'A pass to B, who play wide to C; C pass inside to D; D play a one-two with E, run round the mannequin to receive the return and pass to F; F passes across to the start on the opposite side.', 'Everyone follows their pass; rotation A>B>C>D>E>F>opposite group.', 'C sets the ball for D to pass to F.', 'Meet passes at an angle on the half-turn for speed of play.', '14-18', 14, 18, 'half pitch', NULL, NULL, 15.0, false, false, false, NULL, 390),
  ('Positional rotational combinations with switch', 'passing_unopposed', 'unopposed', 'in_possession', 97, 97, 'Extensive Practice 14', NULL, 'Switching play, tactical combinations and progressive patterns.', 'Same half-pitch two-sided layout with mannequins and two balls from A1 and A2.', 'A to B, B wide to C, C inside to D; D turns inside and switches to E on the opposite side; E passes to F, who plays to the opposite start. Players still rotate on their own side.', 'Rotation A1>B1>C1>D1>E1>F1>A2 and mirror.', 'Builds on Practice 13 with a switch of play.', 'Meet passes at an angle on the half-turn.', '14-18', 14, 18, 'half pitch', NULL, NULL, 15.0, false, false, false, NULL, 400),
  ('Real Madrid breaking lines in pairs (1)', 'passing_unopposed', 'unopposed', 'in_possession', 98, 98, 'Extensive Practice 15', 'Real Madrid', 'Playing forward, breaking lines with attacking waves, support play.', '30 x 15 m with four mannequins; pairs at each end and two middle players C and D.', 'A passes across to B, who plays forward to C; C drops off a mannequin, receives and passes to D, who runs round the other mannequin, receives and plays to E at the far end. A/B become middle players, C/D go to the end, and E/F repeat back the other way.', 'Rotation A & B > C & D > opposite end.', NULL, 'Control, accuracy, timing of movement and body shape.', '10', 10, 10, '30 x 15 m', 30.0, 15.0, 15.0, false, false, true, NULL, 410),
  ('Real Madrid breaking lines in pairs (2)', 'passing_unopposed', 'unopposed', 'in_possession', 99, 99, 'Extensive Practice 16', 'Real Madrid', 'Playing forward, breaking lines with attacking waves, support play.', 'Same 30 x 15 m with mannequins, pairs at each end and two middle players.', 'A to B; D moves wide to take a vertical forward pass from B, plays a one-two with C who shifts across to support, then passes to E. Roles rotate and the pattern runs back the other way.', 'Rotation A & B > C & D > opposite end.', 'Variation of Practice 15.', 'Control, accuracy, timing of movement and body shape.', '10', 10, 10, '30 x 15 m', 30.0, 15.0, 15.0, false, false, true, NULL, 420),
  ('Breaking lines diamond with overlap', 'passing_unopposed', 'unopposed', 'in_possession', 100, 100, 'Extensive Practice 17', NULL, 'Forward passing, breaking lines and wide combinations with an overlap.', '35 x 30 m diamond with a line of mannequins across the middle; two balls from A and C.', 'A/C pass to B/D, who go long then come short, receive and play a through pass for the overlapping run of A/C past the mannequin line; A/C pass to the next player at the start.', 'Rotation A>B>C>D>A.', 'Add passive defenders to pressure the receivers B and D.', 'B drops to meet the pass and A communicates clearly for good timing.', '10-12', 10, 12, '35 x 30 m', 35.0, 30.0, 15.0, false, false, true, NULL, 430),
  ('Breaking lines diamond with underlap', 'passing_unopposed', 'unopposed', 'in_possession', 101, 101, 'Extensive Practice 18', NULL, 'Forward passing, breaking lines and wide combinations with an underlap.', 'Same 35 x 30 m diamond with a mannequin line; two balls.', 'A/C pass to B/D, who make a double movement and play an outside pass for A/C''s inside underlap run to break the mannequin line; A/C then pass to the next player at the start.', 'Rotation A>B>C>D>A.', 'Add passive defenders to pressure B and D.', 'Quality and weight of pass, support angles and timing, communication.', '10-12', 10, 12, '35 x 30 m', 35.0, 30.0, 15.0, false, false, true, NULL, 440),
  ('Third-man overlaps with link players and defenders', 'passing_opposed', 'passive', 'in_possession', 102, 102, 'Extensive Practice 19', NULL, 'Forward passing, wide combination play and breaking lines under pressure.', '35 x 30 m diamond; mannequins replaced by 2 red defenders and 2 yellow link players inside.', 'A/C pass to B/D (go long, come short), who pass inside to a link player; the link player plays in the overlapping run of A/C, who passes to the next player at the start.', 'Rotation A>B>C>D>A; link players vary their movement to support.', 'Variation of Practices 17 and 18.', 'B and link player get open body shapes early for a quicker next pass.', '10-12', 10, 12, '35 x 30 m', 35.0, 30.0, 15.0, false, false, true, NULL, 450),
  ('Breaking lines combination waves in pairs', 'passing_unopposed', 'unopposed', 'in_possession', 103, 103, 'Extensive Practice 20', NULL, 'Forward and progressive passing, switching play and awareness.', '30 x 30 m with a central square of four mannequins; pairs A1/A2 at the bottom, B1/B2 by the top mannequins, C and D pairs at the ends.', 'A1 passes to A2, who plays diagonally through the square for B1''s wide run; B1 opens up and passes diagonally to C1; A1 and A2 sprint to the bottom mannequins while B1/B2 move to C''s spots. C1 to C2, who plays diagonally through for the new B1 and the waves continue.', 'Rotation A1/A2 > B1/B2 > C1/C2 > B1/B2 > D1/D2 and so on.', NULL, 'Weight and accuracy of passes; meet passes quickly with an open body shape.', '10-12', 10, 12, '30 x 30 m', 30.0, 30.0, 15.0, false, false, true, NULL, 460),
  ('Rangers breaking lines forward passing circuit', 'passing_unopposed', 'unopposed', 'in_possession', 104, 104, 'Extensive Practice 21', 'Rangers FC', 'Technical passing, playing forward and breaking lines.', '40 x 30 m with a line of mannequins across the middle as a defensive line, plus mannequins at each corner; two balls from A and C.', 'A/C pass forward to B/D, who open up behind a mannequin, take a directional first touch and play a firm diagonal ground pass through the gaps to the next player at the start.', 'Rotation A>B>C>D>A.', NULL, 'Back-foot first touch, accurate second-touch pass, awareness in tight gaps.', '10-12', 10, 12, '40 x 30 m', 40.0, 30.0, 15.0, false, false, true, NULL, 470),
  ('Rangers breaking lines dribble and finish', 'finishing', 'unopposed', 'in_possession', 105, 105, 'Extensive Practice 22', 'Rangers FC', 'Technical passing, playing forward, breaking lines, dribbling and finishing.', 'Same 40 x 30 m mannequin layout with a goal and GK added at the top.', 'A/C pass forward to B/D, who open up behind a mannequin, then dribble through the mannequin line and shoot. As soon as the shot goes in the next player at A/C starts.', 'Rotation A>B>C>D>A.', 'Progression of Practice 21.', 'Back-foot first touch, ball close when dribbling at speed, precision in tight spaces.', '10-12', 10, 12, '40 x 30 m', 40.0, 30.0, 15.0, true, true, true, NULL, 480),
  ('Two-way forward passing, wide combo and finish', 'finishing', 'unopposed', 'in_possession', 106, 106, 'Extensive Practice 23', NULL, 'Forward passing, wide combination play and finishing.', '40 x 30 m with a goal and GK at each end; group of 10 with balls starting at A and D.', 'A/D pass to B/E, who set back (one-two); A/D then pass to C/F, who take a directional touch past a cone towards goal and side-foot a finish. C/F then join the other group.', 'Rotation A/D > B/E > C/F > opposite group.', NULL, 'Pass weight and accuracy, first touch to set up the finish, communication, controlled finishing.', '10', 10, 10, '40 x 30 m', 40.0, 30.0, 12.0, true, true, true, NULL, 490),
  ('Tactical build-up to break lines and finish', 'combination', 'unopposed', 'in_possession', 107, 107, 'Extensive Practice 24', NULL, 'Tactical build-up, playing forward, breaking lines and through passes.', 'Full pitch with mannequins as the opposition shape; players in a team build-up shape (e.g. 3-2-5 from a 4-3-3) with coaches feeding from either side.', 'A coach passes to the GK and the team plays a coach-set pattern through and around the mannequins to finish attacks in the box (e.g. inverted right back into midfield).', 'Patterns set by the coach.', 'Time limit start to finish; all players must touch the ball; 4 players must run into the box.', 'Movements and counter-movements to create space, passes in wide areas, attacking runs into the box.', '11-22', 11, 22, 'full pitch', NULL, NULL, 15.0, true, true, true, NULL, 500)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
